import{_ as r,o as i,c as l,j as e,a as n,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Rufnamen und alle Vornamen korrekt führen","description":"","frontmatter":{"title":"Rufnamen und alle Vornamen korrekt führen","source_pageid":1494,"source_revision":6075},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/alle-vornamen-anpassen-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/alle-vornamen-anpassen-gruppenprozesse-allgemein.md"}'),t={name:"schild3/suchen-gruppenprozesse/alle-vornamen-anpassen-gruppenprozesse-allgemein.md"};function o(d,a,u,m,p,h){return i(),l("div",null,[...a[0]||(a[0]=[e("h1",{id:"rufnamen-und-alle-vornamen-korrekt-fuhren",tabindex:"-1"},[n("Rufnamen und alle Vornamen korrekt führen "),e("a",{class:"header-anchor",href:"#rufnamen-und-alle-vornamen-korrekt-fuhren","aria-label":'Permalink to "Rufnamen und alle Vornamen korrekt führen"'},"​")],-1),e("p",null,"Unterscheiden Sie Rufname und vollständige Vornamen laut Ausweisdokument. Der Gruppenprozess passt vorhandene Einträge an diese Erfassung an.",-1),e("h2",{id:"angabe-des-vornamen-unter-individualdaten-i",tabindex:"-1"},[n("Angabe des Vornamen unter Individualdaten I "),e("a",{class:"header-anchor",href:"#angabe-des-vornamen-unter-individualdaten-i","aria-label":'Permalink to "Angabe des Vornamen unter Individualdaten I"'},"​")],-1),e("p",null,'Der unter "Rufname" hinterlegte Vorname wird stets im Schülercontainer verwendet. Damit bei offiziellen Angaben des Vornamens stets der offizielle Name aus dem Personalausweis verwendet wird (beispielsweise in Zeugnissen), muss der Vorname wie folgt bei den Individualdaten der Schüler angegeben werden:',-1),e("ul",null,[e("li",null,'Hat die Schülerin oder der Schüler keine weiteren Vornamen, so wird der Vorname im Feld "Rufname" hinterlegt. Das Feld "Alle Vornamen" bleibt leer.'),e("li",null,'Hat eine Schülerin oder ein Schüler mehrere Vornamen, wird zusätzlich zum Rufnamen der vollständige Name (alle Vornamen laut Personalausweis) in das Feld "Alle Vornamen" eingetragen – sofern der Rufname nicht bereits alle Vornamen umfasst.')],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("In älteren SchILD-Versionen findet sich noch das Feld "),e("em",null,"Vorname"),n(", dieses wurde in "),e("em",null,"Rufename"),n(" umbenannt. Steht bei Ihnen noch "),e("em",null,"Vorname"),n(", führen Sie bitte ein Update auf die aktuelle SchILD-Version durch.")])],-1),s('<h2 id="beispiele" tabindex="-1">Beispiele <a class="header-anchor" href="#beispiele" aria-label="Permalink to &quot;Beispiele&quot;">​</a></h2><p><strong>Beispiel 1</strong><br> Offizieller Name laut Personalausweis: Anton Max Theo<br> Rufname: Max</p><p>Eintrag des Vornamens bei den Individualdaten<br> Rufname: Max<br> Alle Vornamen: Anton Max Theo</p><p><strong>Beispiel 2</strong><br> Offizieller Name laut Personalausweis: Hans Peter<br> Rufname: Hans Peter</p><p>Eintrag des Vornamens bei den Individualdaten<br> Rufname: Hans Peter<br> Alle Vornamen: ---</p><p><strong>Beispiel 3</strong><br> Offizieller Name laut Personalausweis: Tina<br> Rufname: Tina</p><p>Eintrag des Vornamens bei den Individualdaten<br> Rufname: Tina<br> Alle Vornamen: ---</p><h2 id="der-gruppenprozess-alle-vornamen-anpassen" tabindex="-1">Der Gruppenprozess Alle Vornamen anpassen <a class="header-anchor" href="#der-gruppenprozess-alle-vornamen-anpassen" aria-label="Permalink to &quot;Der Gruppenprozess Alle Vornamen anpassen&quot;">​</a></h2><p>Um fehlerhafte Einträge bei den Vornamen der Schülerinnen und Schüler zu korrigieren, kann der Gruppenprozess &quot;Alle Vornamen anpassen&quot; angestoßen werden. Dadurch werden bei den Schülern die Felder &quot;Rufname&quot; und &quot;Alle Vornamen&quot; nach folgendem Vorgehen angepasst:</p><ul><li>Ist das Feld &quot;Alle Vornamen&quot; leer, so bleiben die Namenseinträge unverändert.</li><li>Ist das Feld &quot;Alle Vornamen&quot; nicht leer aber bereits korrekt gefüllt, so bleiben die Namenseinträge unverändert. In diesem Fall ist der Rufname bereits im Feld &quot;Alle Vornamen&quot; aufgelistet.</li><li>Ist das Feld &quot;Alle Vornamen&quot; nicht leer und der Rufname ist dort nicht mit aufgelistet, so wird der Rufname in das Feld &quot;Alle Vornamen&quot; integriert.</li></ul><p>Beispiel:</p><p>Rufname: Miriam</p><p>Alle Vornamen: Anna Tina</p><p>wird zu</p><p>Rufname: Miriam</p><p>Alle Vornamen: Miriam Anna Tina</p><p>Hinweis: Ist der offizielle Vorname in dem Beispiel Anna Miriam Tina (Rufname ist nicht der erste Vorname), ist eine manuelle Korrektur notwendig.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Alle_Vornamen_anpassen_(Gruppenprozesse_Allgemein)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6075.</p>',19)])])}const g=r(t,[["render",o]]);export{c as __pageData,g as default};
